from functools import wraps
from typing import Callable, Any, List

def roles_required(*required_role_names: str) -> Callable:
    """
    Decorator that ensures the current user is logged in and has all of the specified roles (AND operation).

    Parameters:
        *required_role_names (str): Variable length argument list of role names.

    Returns:
        Callable: The decorated view function.

    Example:
        @route('/escape')
        @roles_required('Special', 'Agent')
        def escape_capture():  # User must be 'Special' AND 'Agent'
            ...

    Behavior:
        - Calls `unauthenticated_view()` when the user is not logged in or has not confirmed their email address.
        - Calls `unauthorized_view()` when the user does not have the required roles.
        - Calls the decorated view otherwise.
    """
    def decorator(view_function: Callable) -> Callable:
        @wraps(view_function)
        def wrapped_view(*args: Any, **kwargs: Any) -> Any:
            # Check if the user is authenticated and has the required roles
            if not user.is_authenticated or not user.has_roles(*required_role_names):
                # Redirect to the unauthorized page
                return app.login_manager.unauthorized()

            # Call the original view function if the user has the required roles
            return view_function(*args, **kwargs)
        return wrapped_view
    return decorator

# Example usage of the roles_required decorator
