    from flask import Flask, redirect, url_for, render_template_string
    from flask_login import LoginManager, UserMixin, login_user

    app = Flask(__name__)
    app.secret_key = 'supersecretkey'
    login_manager = LoginManager()
    login_manager.init_app(app)

    class User(UserMixin):
        def __init__(self, id: int, roles: List[str]):
            self.id = id
            self.roles = roles

        def has_roles(self, *roles: str) -> bool:
            return all(role in self.roles for role in roles)

    @login_manager.user_loader
    def load_user(user_id: str) -> User:
        return User(int(user_id), ['Special', 'Agent'])

    @app.route('/')
    def index():
        return "Welcome to the home page!"

    @app.route('/escape')
    @roles_required('Special', 'Agent')
    def escape_capture():
        return "You have escaped the capture!"

    @app.route('/login')
    def login():
        user_to_login = load_user('1')  # Simulate user login
        login_user(user_to_login)
        return redirect(url_for('index'))

    @app.route('/unauthorized')
    @login_manager.unauthorized_handler
    def unauthorized():
        return render_template_string("<p>Unauthorized access</p>")

    app.run(debug=True)

